  @LocalServerPort int port;

  /** The settings of {@link #registerSettings} as plain values, for starting the app directly. */
  static Map<String, Object> settingsMap(Map<String, String> overrides) {
    Map<String, Object> values = new LinkedHashMap<>();
    registerSettings(
        new DynamicPropertyRegistry() {
          @Override
          public void add(String name, Supplier<Object> valueSupplier) {
            values.put(name, valueSupplier.get());
          }
        },
        overrides);
    return values;
  }

  /** Default settings of the acceptance context; {@code overrides} replace single settings. */
  static void registerSettings(DynamicPropertyRegistry registry, Map<String, String> overrides) {
    Map<String, Supplier<Object>> settings = new LinkedHashMap<>();
    settings.put("APP_ENVIRONMENT", () -> "test");
    settings.put("DB_URL", POSTGRES::getJdbcUrl);
    settings.put("DB_USER", () -> DB_USER);
    settings.put("POSTGRES_PASSWORD", () -> DB_PASSWORD);
    settings.put("SMTP_HOST", MAILPIT::getHost);
    settings.put("SMTP_PORT", () -> String.valueOf(MAILPIT.getMappedPort(1025)));
    settings.put("SMTP_TLS", () -> "false");
    settings.put("MAIL_FROM", () -> "registration@test.local");
    settings.put("ORGANIZER_EMAILS", () -> String.join(",", ORGANIZER_EMAILS));
    settings.put("ORGANIZER_USERNAME", () -> ORGANIZER_USERNAME);
    settings.put("ORGANIZER_PASSWORD", () -> ORGANIZER_PASSWORD);
    settings.put("CONFERENCE_CONFIG_PATH", () -> testConfigPath("conference-test.json"));
    settings.put("JSON_COPY_DIR", () -> JSON_COPY_DIR.toAbsolutePath().toString());
    settings.put("CAPTCHA_TEST_MODE", () -> "true");
    settings.put("RECAPTCHA_SITE_KEY", () -> "");
    settings.put("RECAPTCHA_SECRET_KEY", () -> "");
    settings.put("ORGANIZER_HTTPS_ONLY", () -> "true");
    settings.put("RATE_LIMIT_PER_MINUTE", () -> "100000");
    overrides.forEach((key, value) -> settings.put(key, () -> value));
    settings.forEach(registry::add);
  }

  static String testConfigPath(String fileName) {
    try {
      return Paths.get(AcceptanceTestSupport.class.getResource("/acceptance/" + fileName).toURI())
          .toAbsolutePath()
          .toString();
    } catch (URISyntaxException e) {
      throw new IllegalStateException(e);
    }
  }

  @BeforeEach
  void cleanState() throws Exception {
    try (Connection c = db();
        Statement s = c.createStatement();
        ResultSet rs =
            s.executeQuery(
                "SELECT count(*) FROM information_schema.tables WHERE table_name = 'registration'")) {
      rs.next();
      if (rs.getInt(1) > 0) {
        s.execute("TRUNCATE registration CASCADE");
      }
    }
    if (!Files.isDirectory(JSON_COPY_DIR)) {
      Files.deleteIfExists(JSON_COPY_DIR);
      Files.createDirectories(JSON_COPY_DIR);
    }
    try (Stream<Path> files = Files.list(JSON_COPY_DIR)) {
      for (Path f : files.toList()) {
        Files.delete(f);
      }
    }
    mailpit("DELETE", "/api/v1/messages");
  }

  // ---- requests ----

  static Map<String, Object> validExternal() {
    Map<String, Object> body = new LinkedHashMap<>();
    body.put("type", "EXTERNAL");
    body.put("firstName", "Ana");
    body.put("lastName", "Novak");
    body.put("email", "ana.novak@example.org");
    body.put("organization", "Example d.o.o.");
    body.put("studyInstitution", null);
    body.put("studyProgramme", null);
    body.put("studentId", null);
    body.put("options", new ArrayList<>(List.of("ws-ai", "ev-gala")));
    body.put("consents", new ArrayList<>(List.of("privacy")));
    body.put("captchaToken", "test-pass");
    return body;
  }

  static Map<String, Object> validStudent() {
    Map<String, Object> body = new LinkedHashMap<>();
    body.put("type", "STUDENT");
    body.put("firstName", "Luka");
    body.put("lastName", "Horvat");
    body.put("email", "luka.horvat@student.example.org");
    body.put("organization", null);
    body.put("studyInstitution", "University of Ljubljana");
    body.put("studyProgramme", "Computer Science");
    body.put("studentId", "63210001");
    body.put("options", new ArrayList<>(List.of("ws-ai", "ev-student")));
    body.put("consents", new ArrayList<>(List.of("privacy")));
    body.put("captchaToken", "test-pass");
    return body;
  }

  String url(String path) {
    return "http://127.0.0.1:" + port + path;
  }

  HttpResponse<String> postRegistration(Object body) throws Exception {
    return postJson("/api/registrations", json.writeValueAsString(body));
  }

  HttpResponse<String> postJson(String path, String body) throws Exception {
    HttpRequest request =
        HttpRequest.newBuilder(URI.create(url(path)))
            .timeout(Duration.ofSeconds(60))
            .header("Content-Type", "application/json; charset=utf-8")
            .POST(HttpRequest.BodyPublishers.ofString(body, StandardCharsets.UTF_8))
            .build();
    return http.send(request, HttpResponse.BodyHandlers.ofString(StandardCharsets.UTF_8));
  }

  HttpResponse<String> get(String path, String... headers) throws Exception {
    return http.send(getRequest(path, headers), HttpResponse.BodyHandlers.ofString());
  }

  HttpResponse<byte[]> getBytes(String path, String... headers) throws Exception {
    return http.send(getRequest(path, headers), HttpResponse.BodyHandlers.ofByteArray());
  }

  private HttpRequest getRequest(String path, String... headers) {
    HttpRequest.Builder b =
        HttpRequest.newBuilder(URI.create(url(path))).timeout(Duration.ofSeconds(60)).GET();
    if (headers.length > 0) {
      b.headers(headers);
    }
    return b.build();
  }

  static String basicAuth(String user, String password) {
    return "Basic "
        + Base64.getEncoder()
            .encodeToString((user + ":" + password).getBytes(StandardCharsets.UTF_8));
  }

  JsonNode jsonBody(HttpResponse<String> response) {
    return json.readTree(response.body());
  }

  /** Asserts HTTP 201 and returns the new registration id. */
  String createdId(HttpResponse<String> response) {
    assertThat(response.statusCode()).as("status, body: %s", response.body()).isEqualTo(201);
    String id = jsonBody(response).path("id").asString();
    assertThat(id).isNotBlank();
    return id;
  }

  /** Field names of a 400 response body {"errors": [{"field", "message"}]}. */
  List<String> errorFields(HttpResponse<String> response) {
    assertThat(response.statusCode()).as("status, body: %s", response.body()).isEqualTo(400);
    JsonNode errors = jsonBody(response).path("errors");
    assertThat(errors.isArray()).as("errors array in %s", response.body()).isTrue();
    List<String> fields = new ArrayList<>();
    for (JsonNode e : errors) {
      assertThat(e.path("message").asString()).isNotBlank();
      fields.add(e.path("field").asString());
    }
    return fields;
  }
}
package si.konferenca.registration.acceptance;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.nio.file.Files;
import java.nio.file.Path;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Statement;
import java.time.Duration;
import java.time.OffsetDateTime;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Stream;
import org.testcontainers.containers.GenericContainer;
import org.testcontainers.containers.wait.strategy.Wait;
import org.testcontainers.postgresql.PostgreSQLContainer;
import org.testcontainers.utility.DockerImageName;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.json.JsonMapper;

/**
 * Probes of the acceptance tests into the systems the backend writes to: PostgreSQL (schema of
 * docs/02_contracts/database-schema.sql), the JSON copy directory and Mailpit (SMTP server). The
 * containers start once per test JVM.
 */
abstract class AcceptanceProbes {

  static final String DB_NAME = "registration";
  static final String DB_USER = "registration";
  static final String DB_PASSWORD = "registration-test";

  static final PostgreSQLContainer POSTGRES =
      new PostgreSQLContainer(DockerImageName.parse("postgres:16.15-alpine"))
          .withDatabaseName(DB_NAME)
          .withUsername(DB_USER)
          .withPassword(DB_PASSWORD);

  static final GenericContainer<?> MAILPIT =
      new GenericContainer<>(DockerImageName.parse("axllent/mailpit:v1.31.1"))
          .withExposedPorts(1025, 8025)
          .waitingFor(Wait.forHttp("/api/v1/info").forPort(8025));

  static final Path JSON_COPY_DIR;

  static {
    POSTGRES.start();
    MAILPIT.start();
    try {
      JSON_COPY_DIR = Files.createTempDirectory("acceptance-json-copies");
    } catch (IOException e) {
      throw new UncheckedIOException(e);
    }
  }

  private static final Duration MAIL_WAIT = Duration.ofSeconds(15);

  final HttpClient http = HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(10)).build();
  final JsonMapper json = JsonMapper.builder().build();

  /** "Rejected" (acceptance-criteria.md): no database row, no JSON copy, no email. */
  void assertNothingStored() throws Exception {
    assertThat(registrationCount()).as("registrations in the database").isZero();
    assertThat(jsonCopyCount()).as("JSON copies").isZero();
    Thread.sleep(500);
    assertThat(messages()).as("emails in Mailpit").isEmpty();
  }

  // ---- database (docs/02_contracts/database-schema.sql) ----

  static Connection db() throws SQLException {
    return DriverManager.getConnection(POSTGRES.getJdbcUrl(), DB_USER, DB_PASSWORD);
  }

  static int registrationCount() throws SQLException {
    try (Connection c = db();
        Statement s = c.createStatement();
        ResultSet rs =
            s.executeQuery(
                "SELECT count(*) FROM information_schema.tables WHERE table_name = 'registration'")) {
      rs.next();
      if (rs.getInt(1) == 0) {
        return 0;
      }
    }
    try (Connection c = db();
        Statement s = c.createStatement();
        ResultSet rs = s.executeQuery("SELECT count(*) FROM registration")) {
      rs.next();
      return rs.getInt(1);
    }
  }

  /** Column name to value; text columns as String, registered_at as OffsetDateTime. */
  static Map<String, Object> registrationRow(String id) throws SQLException {
    try (Connection c = db();
        PreparedStatement ps =
            c.prepareStatement(
                "SELECT type, first_name, last_name, email, organization, study_institution,"
                    + " study_programme, student_id, registered_at FROM registration"
                    + " WHERE id = CAST(? AS uuid)")) {
      ps.setString(1, id);
      try (ResultSet rs = ps.executeQuery()) {
        assertThat(rs.next()).as("registration row %s", id).isTrue();
        Map<String, Object> row = new LinkedHashMap<>();
        for (String col :
            List.of(
                "type",
                "first_name",
                "last_name",
                "email",
                "organization",
                "study_institution",
                "study_programme",
                "student_id")) {
          row.put(col, rs.getString(col));
        }
        row.put("registered_at", rs.getObject("registered_at", OffsetDateTime.class));
        return row;
      }
    }
  }

  static List<String> optionIds(String id) throws SQLException {
    List<String> ids = new ArrayList<>();
    try (Connection c = db();
        PreparedStatement ps =
            c.prepareStatement(
                "SELECT option_id FROM registration_option WHERE registration_id = CAST(? AS uuid)"
                    + " ORDER BY option_id")) {
      ps.setString(1, id);
      try (ResultSet rs = ps.executeQuery()) {
        while (rs.next()) {
          ids.add(rs.getString(1));
        }
      }
    }
    return ids;
  }

  /** Consent id to the time it was given. */
  static Map<String, OffsetDateTime> consents(String id) throws SQLException {
    Map<String, OffsetDateTime> result = new LinkedHashMap<>();
    try (Connection c = db();
        PreparedStatement ps =
            c.prepareStatement(
                "SELECT consent_id, given_at FROM registration_consent"
                    + " WHERE registration_id = CAST(? AS uuid) ORDER BY consent_id")) {
      ps.setString(1, id);
      try (ResultSet rs = ps.executeQuery()) {
        while (rs.next()) {
          result.put(rs.getString(1), rs.getObject(2, OffsetDateTime.class));
        }
      }
    }
    return result;
  }

  // ---- JSON copies (docs/02_contracts/registration-copy.schema.json) ----

  static Path jsonCopy(String id) {
    return JSON_COPY_DIR.resolve(id + ".json");
  }

  static long jsonCopyCount() throws IOException {
    if (!Files.isDirectory(JSON_COPY_DIR)) {
      return 0;
    }
    try (Stream<Path> files = Files.list(JSON_COPY_DIR)) {
      return files.filter(f -> f.getFileName().toString().endsWith(".json")).count();
    }
  }

  // ---- Mailpit API ----

  static String mailpitUrl(String path) {
    return "http://" + MAILPIT.getHost() + ":" + MAILPIT.getMappedPort(8025) + path;
  }

  HttpResponse<byte[]> mailpit(String method, String path) throws Exception {
    HttpRequest request =
        HttpRequest.newBuilder(URI.create(mailpitUrl(path)))
            .timeout(Duration.ofSeconds(30))
            .method(method, HttpRequest.BodyPublishers.noBody())
            .build();
    HttpResponse<byte[]> response = http.send(request, HttpResponse.BodyHandlers.ofByteArray());
    assertThat(response.statusCode()).as("Mailpit %s %s", method, path).isEqualTo(200);
    return response;
  }

  /** Summaries of all messages in Mailpit. */
  List<JsonNode> messages() throws Exception {
    JsonNode list = json.readTree(mailpit("GET", "/api/v1/messages?limit=500").body());
    List<JsonNode> result = new ArrayList<>();
    for (JsonNode m : list.path("messages")) {
      result.add(m);
    }
    return result;
  }

  /** Waits until at least {@code count} messages arrived, then lets stragglers arrive too. */
  List<JsonNode> awaitMessages(int count) throws Exception {
    long deadline = System.nanoTime() + MAIL_WAIT.toNanos();
    while (messages().size() < count && System.nanoTime() < deadline) {
      Thread.sleep(200);
    }
    Thread.sleep(500);
    return messages();
  }

  /** Full message: From, To, Cc, Bcc, Subject, Text, HTML, Attachments. */
  JsonNode message(JsonNode summary) throws Exception {
    return json.readTree(mailpit("GET", "/api/v1/message/" + summary.path("ID").asString()).body());
  }

  /** Header name to values. */
  JsonNode headers(JsonNode summary) throws Exception {
    return json.readTree(
        mailpit("GET", "/api/v1/message/" + summary.path("ID").asString() + "/headers").body());
  }

  byte[] attachment(JsonNode fullMessage, JsonNode attachment) throws Exception {
    return mailpit(
            "GET",
            "/api/v1/message/"
                + fullMessage.path("ID").asString()
                + "/part/"
                + attachment.path("PartID").asString())
        .body();
  }

  /** Every address in To, Cc and Bcc of a message, lower case. */
  static List<String> recipients(JsonNode message) {
    List<String> result = new ArrayList<>();
    for (String field : List.of("To", "Cc", "Bcc")) {
      for (JsonNode a : message.path(field)) {
        result.add(a.path("Address").asString().toLowerCase(java.util.Locale.ROOT));
      }
    }
    return result;
  }

  /** Messages whose recipients include {@code address}. */
  static List<JsonNode> messagesTo(List<JsonNode> messages, String address) {
    return messages.stream().filter(m -> recipients(m).contains(address.toLowerCase())).toList();
  }
}
